/*
 * Situational (conditional) bonuses granted by feats.
 *
 * Many feats grant a bonus that only applies in specific circumstances — Intimidating Prowess gives
 * +1 to Intimidation *when you Coerce or Demoralize a target you can physically menace*. The build
 * engine can't fold these into a flat number (they're conditional), so instead the sheet FLAGS the
 * affected stat (a * next to Intimidation) and lists the condition when the player opens that stat's
 * detail — so they know they have something that applies here.
 *
 * The registry is authored from the Foundry pf2e rule elements (predicated FlatModifiers on a
 * skill/save/perception/AC selector) plus each feat's printed text. It is DISPLAY-ONLY: nothing here
 * changes a computed number. Keyed by the feat's core.json id.
 */
import type { ProficiencyKey } from './types';

export interface SituationalTarget {
  /**
   * Which stat the bonus can apply to. These deliberately mirror `StatRef` in explain.ts: a target
   * that cannot be expressed as a StatRef can never be displayed, so the two vocabularies have to
   * agree. (Authoring this union from the display side is exactly the mistake that left 338 verified
   * bonuses — strikeDamage, speed, spell, hp, classDc, ability — with nowhere to be stored.)
   *
   * `attack` is the legacy spelling of `strikeAttack`; both match a strike's attack roll.
   */
  kind:
    | 'skill'
    | 'save'
    | 'perception'
    // Initiative READS another statistic (Perception by default, a skill when the character rolls
    // it with one). Bonuses that apply to WHATEVER you roll live here; ones that name Perception
    // specifically stay on `perception` and still surface, because the Initiative breakdown includes
    // the underlying statistic's lines.
    | 'initiative'
    | 'ac'
    | 'attack'
    | 'strikeAttack'
    | 'strikeDamage'
    | 'speed'
    | 'hp'
    | 'classDc'
    | 'spell'
    | 'spellDamage'
    | 'ability';
  /**
   * For `skill`: a skill key (e.g. `intimidation`), a `lore:*` key, or `all` (any skill).
   * For `save`: `fortitude` | `reflex` | `will` | `all`.
   * For `spell`: `dc` | `attack` | `all`.
   * For `ability`: an ability key (e.g. `str`) or `all`.
   * Ignored for `spellDamage` — the damage your spells deal has no sub-stat.
   * Ignored for the rest.
   *
   * ⚠ `spellDamage` is PROSE ONLY, on purpose. Every entry renders a "when" the player reads and
   * applies themselves, so it cannot be wrong about which spells it covers. If this ever becomes a
   * NUMBER, read `Spell.damageKind` first: 31 spells heal, and "+2 to your spell damage" must not
   * add +2 to a heal. Per record though — Sorcerous Potency says "deals damage OR RESTORES HIT
   * POINTS" and means both; Dangerous Sorcery says "deals damage" and does not.
   * See the comment on `Spell.damageKind` and `test/parked-fields.test.ts`.
   */
  detail?: string;
  /**
   * `save` only: the bonus moves the SAVE DC — the number other creatures roll against — and not the
   * save you roll yourself. Six-Fingers Elixir raises your Reflex DC against being tripped; it does
   * nothing for your own Reflex save.
   *
   * Ruling D puts these in the save's popup so they are readable, worded to say which number they
   * touch, but the `*` goes beside the DC rather than beside the save's name. Marking the save name
   * would promise a bonus to a roll that never gets one.
   */
  dcOnly?: boolean;
}

export interface SituationalBonus {
  targets: SituationalTarget[];
  /** Short, player-facing trigger, e.g. "you Coerce or Demoralize a target you can physically menace". */
  when: string;
  /** The modifier, e.g. "+1 circumstance", or a short effect phrase. */
  bonus: string;
}

