/** A StatRef, loosened so callers outside explain.ts can pass a plain object. */
type RefLike = { kind: string; skill?: string; save?: string; which?: string; ability?: string };

/** Does a StatRef-like target match a registry target? `all` matches any of that kind. */
function targetMatches(t: SituationalTarget, ref: RefLike): boolean {
  switch (t.kind) {
    case 'skill': {
      if (ref.kind !== 'skill') return false;
      if (t.detail === 'all') return true;
      /*
       * Lore keys are `lore:<subject>` where the SUBJECT IS TYPED BY THE PLAYER — "Warfare",
       * "warfare", "Guild" — so an exact `===` against a registry entry authored as `lore:games` can
       * miss on capitalisation alone, and the 20 entries written `lore:*` or bare `lore` (meaning
       * "any Lore") could never match anything at all. Both were silently dead.
       *
       * A wildcard is the only shape that can work for "a Lore skill you're trained in": the registry
       * cannot enumerate subjects it does not know.
       */
      const detail = String(t.detail ?? '');
      const skill = String(ref.skill ?? '');
      if (detail === 'lore' || detail === 'lore:*') return skill.startsWith('lore:');
      if (detail.startsWith('lore:') && skill.startsWith('lore:')) return detail.toLowerCase() === skill.toLowerCase();
      return detail === skill;
    }
    case 'save':
      return ref.kind === 'save' && (t.detail === 'all' || t.detail === ref.save);
    case 'perception':
      return ref.kind === 'perception';
    // An initiative bonus applies to whatever statistic you roll it with, so it matches ONLY the
    // initiative ref — never Perception. A Perception-SPECIFIC one ("on Perception checks rolled for
    // initiative") stays targeted at `perception` and reaches the Initiative row through that
    // breakdown's delegation instead, so neither kind is lost and neither double-counts.
    case 'initiative':
      return ref.kind === 'initiative';
    case 'ac':
      return ref.kind === 'ac';
    // `attack` predates `strikeAttack`; the hand-authored anchors still use it.
    case 'attack':
    case 'strikeAttack':
      return ref.kind === 'strikeAttack';
    case 'strikeDamage':
      return ref.kind === 'strikeDamage';
    case 'speed':
      return ref.kind === 'speed';
    case 'hp':
      return ref.kind === 'hp';
    case 'classDc':
      return ref.kind === 'classDc';
    // A spell entry's DC and attack roll are separate rows, so `dc`/`attack` narrow to one of them.
    case 'spell':
      return ref.kind === 'spell' && (!t.detail || t.detail === 'all' || t.detail === ref.which);
    // Damage DEALT BY YOUR SPELLS — a separate surface from `spell` (the attack roll and DC) and from
    // `strikeDamage` (weapons only). Dangerous Sorcery and Channeler's Stance land here; putting them
    // on `spell` would star the attack roll and DC, neither of which they touch.
    case 'spellDamage':
      return ref.kind === 'spellDamage';
    case 'ability':
      return ref.kind === 'ability' && (!t.detail || t.detail === 'all' || t.detail === ref.ability);
    default:
      return false;
  }
}

/**
 * Extra entries beyond the shipped registry, keyed the same way (by the id of the thing granting
 * them). The item editor's Advanced section writes these onto an item, so a player can mark a
 * conditional effect the data doesn't carry — or one their table rules differently — and have it
 * behave exactly like a shipped one. Looked up in addition to FEAT_SITUATIONAL, never instead of it,
 * so an authored entry on an item that also ships entries ADDS to them rather than replacing them.
 */
export type ExtraSituational = Readonly<Record<string, readonly SituationalBonus[] | undefined>>;

/**
 * A DEGREE-OF-SUCCESS shift — "if you roll a success on a Thievery check to Pick a Lock, you get a
 * critical success instead". No number moves, so no numeric lane can carry it.
 *
 * Owner ruling Q2: it stars **both** the skill and the action it names, and all three saves when it
 * applies to saves generally. That is why this is ONE field rather than two registry entries. Before
 * it existed the halves had to be hand-authored into separate registries with nothing keeping them in
 * step, and no shipped record actually satisfied the ruling: `steadying-stone` starred Acrobatics and
 * left the Balance action bare, while `sure-feet` marked the Balance and Climb actions and left
 * Acrobatics bare. One entry now fans out to every surface it names, so they cannot disagree.
 */
export interface DegreeShift {
  /** Which way the result moves. `oneBetter` shifts every degree up one step. */
  shift: 'successToCrit' | 'critFailToFail' | 'oneBetter' | 'failToSuccess';
  /** The trigger, printed verbatim in the note — "on a check to Pick a Lock". */
  when: string;
  /** Skill keys to star, or `['all']`. */
  skills?: string[];
  /** Save ids to star, or `['all']` — Q2: a general save clause stars all three. */
  saves?: string[];
  /** Action ids to mark. Matched against the SLUGIFIED action name, as `RecordMarker.id` is. */
  actions?: string[];
  /**
   * Star PERCEPTION too — "when you succeed at a Perception check against an illusion, you get a
   * critical success instead" (Cryolite Eye), "to disbelieve an illusion" (Disillusionment).
   *
   * Q2 names the skill and the action, not Perception, because the audit sample was skill- and
   * save-shaped. But Perception is a row the player looks a number up on exactly as a skill is, and
   * three records already shipped a hand-written Perception star for a degree shift. Without this
   * flag, converting them to the structured field would have DELETED a surface that works today —
   * the conversion has to be able to say everything the prose said, or it is a regression dressed as
   * a refactor. A boolean rather than a list because Perception is one statistic, not a set.
   */
  perception?: boolean;
}

/** The player-facing phrase for a shift. One source, so the skill star and the action mark agree. */
export const DEGREE_SHIFT_TEXT: Record<DegreeShift['shift'], string> = {
  successToCrit: 'a success is a critical success instead',
  critFailToFail: 'a critical failure is a failure instead',
  failToSuccess: 'a failure is a success instead',
  oneBetter: 'your degree of success is one step better',
};

/** The compact form for an action row's inline `( )` slot, where space is tight. */
export const DEGREE_SHIFT_SHORT: Record<DegreeShift['shift'], string> = {
  successToCrit: 'success → crit success',
  critFailToFail: 'crit fail → fail',
  failToSuccess: 'fail → success',
  oneBetter: 'one degree better',
};

const entriesFor = (id: string, extra?: ExtraSituational): readonly SituationalBonus[] => {
  const shipped = FEAT_SITUATIONAL[id];
  const authored = extra?.[id];
  if (!authored?.length) return shipped ?? [];
  return shipped?.length ? [...shipped, ...authored] : authored;
};

/** The situational bonuses a character's taken feats grant to the given stat (empty if none). */
export function featSituationalFor(
  featIds: Iterable<string>,
  ref: { kind: string; skill?: string; save?: string },
  extra?: ExtraSituational,
): { id: string; when: string; bonus: string; dcOnly?: boolean }[] {
  const out: { id: string; when: string; bonus: string; dcOnly?: boolean }[] = [];
  const seen = new Set<string>();
  for (const id of featIds) {
    if (seen.has(id)) continue;
    seen.add(id);
    for (const b of entriesFor(id, extra)) {
      const hit = b.targets.find((t) => targetMatches(t, ref));
      // `dcOnly` travels with the MATCHED target, not the entry: one entry can name a save DC and an
      // ordinary skill check, and only the save half belongs beside the DC.
      if (hit) out.push({ id, when: b.when, bonus: b.bonus, ...(hit.dcOnly ? { dcOnly: true } : {}) });
    }
  }
  return out;
}

/**
 * A star whose TARGET is the PLAYER'S OWN ANSWER, supplied at display time.
 *
 * `FEAT_SITUATIONAL` names its targets outright, which only works when the affected stat is knowable
 * when the entry is written. Assurance's is not — "choose a skill you're trained in" means the target
 * is whichever skill this player picked, on this character, for this taking of a repeatable feat.
 * There is no id to key a static entry to.
 *
 * The star is still required. Ruling Q20: *"remember Assurance needs to have a `*` on the skill that
 * it affects."* Assurance moves no number — you take 10 + your proficiency bonus instead of rolling —
 * so the skill row is the ONLY place a player would ever learn the feat reaches it. The same is true
 * of every record below: each asks for a skill and then acts on that skill without changing its
 * modifier, which is exactly the shape Q20's second test question was written for.
 *
 * Only the PROSE lives here, because the prose is the same for every taking; the target arrives from
 * the character (see `choiceSituationalFor`).
 *
 * Two shapes, and which one applies is decided by `skill`:
 *   - ABSENT — the answer IS the target. It is read as a skill key (`athletics`, `lore:games`), so
 *     the record must ask a `kind: 'skills'` choice. Assurance's shape.
 *   - PRESENT — the target is fixed and the ANSWER is what the line has to say. Shooter's Camouflage
 *     asks for a terrain and then changes what Stealth does there; the terrain is no skill, so a
 *     record like this could not exist here until the field did.
 */
export interface ChoiceSituational {
  /** Short, player-facing trigger — as in `SituationalBonus`. `{answer}` is replaced by the player's
   *  own answer, so one entry serves every possible pick without restating the prose per option. */
  when: string;
  /** What it gives. Prose, not a modifier: none of these move a number. */
  bonus: string;
  /**
   * The skill the star lands on, when the answer is NOT itself a skill.
   *
   * Ruling Q20's second test question is "does the choice name a specific STAT?" — and it is asked of
   * the FEAT, not of the answer's vocabulary. Shooter's Camouflage names Hide and Sneak, both Stealth
   * actions, so Stealth is where the player looks the number up and where the mark belongs (ruling J:
   * *"situational stars go on the specific skills or actions affected"*).
   */
  skill?: ProficiencyKey;
}
export const CHOICE_SITUATIONAL: Record<string, ChoiceSituational[]> = {
  // Ruling Q20, verbatim: "remember Assurance needs to have a `*` on the skill that it affects."
  // Reached by a granted Assurance too (Eidetic Ear, Weight of Experience, Quah Bond, Gnome
  // Obsession) — the granted feat carries its own answer on the character, so one entry covers all.
  "assurance": [{ when: "you forgo the roll; no other bonus, penalty or modifier applies", bonus: "take 10 + your proficiency bonus instead of rolling" }],
  // Prerequisite is "Assurance in that skill", so this star sits beside Assurance's own on the same
  // skill — two different things the player does with it, and both belong where they look it up.
  "automatic-knowledge": [{ when: "to Recall Knowledge with this skill, once per round", bonus: "a free action, and you must use Assurance" }],
  // The chosen skill REPLACES Deception for this one use. Not a `skillSubstitutions` entry: that
  // field names its skills on the record, and this one's is the player's answer.
  "masterful-obfuscation": [{ when: "when you Lie about facts related to this skill's subject", bonus: "roll this skill instead of Deception" }],
  "heroic-scion-dedication": [{ when: "on an action using this skill, if you spend a Mythic Point", bonus: "attempt the check at mythic proficiency" }],
  // Ruling Q20 on an echo-only picker: the terrain answer moved nothing and appeared nowhere but the
  // feat's own row, yet the feat plainly names two Stealth actions. No number changes — you still roll
  // Stealth at the same modifier — so the star is the whole surface, and the ANSWER is the half of the
  // sentence that decides whether it applies at all. `{answer}` carries it.
  "shooters-camouflage": [{ skill: 'stealth', when: "in {answer}", bonus: "Hide and Sneak even without cover and without being concealed" }],
};

/**
 * The entries a record contributes once its choice is answered — the static prose above, aimed at
 * the skill the player named (or, where `skill` is set, at that skill, with the answer spelled into
 * the trigger).
 *
 * Returns the ordinary `SituationalBonus` shape so the synthesised entry travels the same display
 * path as a shipped one and there is no second renderer to keep in step.
 *
 * `answerLabel` is the human wording of the same answer ("Natural terrain" for `natural`). Passed
 * separately rather than derived here, because deriving it would need the content database and this
 * function is deliberately reachable with nothing but the character.
 */
export function choiceSituationalFor(recordId: string, answer: string, answerLabel = answer): SituationalBonus[] {
  const list = CHOICE_SITUATIONAL[recordId];
  if (!list?.length || !answer) return [];
  return list.map((e) => ({
    targets: [{ kind: 'skill', detail: e.skill ?? answer }],
    // Lower-cased because the label is a picker option ("Natural terrain") being pasted mid-sentence.
    when: e.when.replace('{answer}', answerLabel.charAt(0).toLowerCase() + answerLabel.slice(1)),
    bonus: e.bonus,
  }));
}

/** One line of the star list, before it is worded: who grants it, when it applies, and what it gives. */
export interface SituationalLine {
  /** Display name of the source ("Ring of Sure Grip", "Inspire Courage"). */
  source: string;
  when: string;
  /** As printed: "+2 circumstance", "-1 status", or a phrase like "roll d10s instead of d8s". */
  bonus: string;
  /** The record's id, so the line can open its full text — ruling H's "have a place to click to open
   *  the full". Absent for a mode, which has no record behind it to open. */
  sourceId?: string;
  /** Which collection `sourceId` lives in, so the opener can find it without searching all of them. */
  sourceCollection?: 'feats' | 'items' | 'heritages' | 'backgrounds' | 'ancestries' | 'classFeatures';
  /**
   * This changes the SAVE DC other creatures roll against, not a check you roll.
   *
   * Ruling D: such an entry still appears in the save's popup, worded so it plainly says so, but the
   * `*` goes next to the DC rather than next to the save's name — the number it moves is the DC.
   */
  dcOnly?: boolean;
}

/**
 * A mark on an ACTION or a CONDITION rather than on a stat.
 *
 * Some things change no number the sheet holds. Magic Hands makes Treat Wounds heal d10s instead of
 * d8s; Black Powder Boost adds 10 feet to a Leap; The Survivor changes how Dying works for you. None
 * of those has a stat row, and starring "the nearest roll" would be a lie — Magic Hands gives no
 * bonus to the Medicine check at all.
 *
 * The owner's ruling was to attach the mark to the thing it modifies and show the changed value
 * inline: "Magic Hands show the d10 in () in the treat wounds action, with a * linking to the feat".
 * Both surfaces already render on the sheet, so this is where they get their marks.
 */
export interface RecordMarker {
  /** Which surface: an action row, or a condition. */
  on: 'action' | 'condition';
  /** The action's or condition's id in core.json ("treat-wounds", "leap", "dying"). */
  id: string;
  /** The CHANGED value, shown inline in parentheses on that row: "d10", "+10 feet". Omitted when
   *  there is no single value to show and the mark is only the note. */
  value?: string;
  /** One line: what the source does to that action or condition. */
  note: string;
}

