/**
 * Conditional bonuses that belong on a SPELL's row rather than on a stat.
 *
 * Ruling G: "Distant Grasp: on the spell, since that's what you're looking at when you cast it." The
 * class feature is what grants the bonus, but the spell is where the player meets it — a star on some
 * stat row would never be seen at the moment it matters.
 *
 * Keyed by SPELL id; each entry names the record that grants it, so it only shows for a character who
 * actually has that record.
 */
export interface SpellMarker {
  /** The feat / class feature / item that grants it — the character must have this. */
  source: string;
  when: string;
  bonus: string;
}
export const SPELL_MARKERS: Record<string, SpellMarker[]> = {
  "harm": [{ source: 'sap-life', when: "when your harm damages at least one living creature, and you are living", bonus: "regain HP equal to the spell rank" }],
  "dancing-blade": [{ source: 'the-distant-grasp', when: "while an amped dancing blade Guards you — vs melee attacks…", bonus: "+2 circumstance" }],
};

/** The markers on this spell that the character's own records grant. */
export function spellMarkersFor(spellId: string, ownedIds: Iterable<string>): SpellMarker[] {
  const list = SPELL_MARKERS[spellId];
  if (!list?.length) return [];
  const owned = new Set(ownedIds);
  return list.filter((m) => owned.has(m.source));
}

/**
 * Records whose entry REPLACES another's rather than sitting beside it.
 *
 * Ruling G: "Relic set: the set entry replaces the piece's, so you read one line, not two." A relic
 * that upgrades one of its own pieces would otherwise star the same stat twice — once for the piece
 * and once for the completed set — and the player would have to work out that they don't add up.
 *
 * Keyed set id → the ids it supersedes. Only applies when the character actually has both.
 */
export const SITUATIONAL_SUPERSEDES: Record<string, string[]> = {
  "seers-array": ['recalculate'],
};

/** The ids to drop from a lookup because a record the character ALSO has supersedes them. */
export function supersededIds(ownedIds: Iterable<string>): Set<string> {
  const owned = new Set(ownedIds);
  const out = new Set<string>();
  for (const id of owned) for (const gone of SITUATIONAL_SUPERSEDES[id] ?? []) if (owned.has(gone)) out.add(gone);
  return out;
}

/** Every mark this character's records put on one action or condition. */
export function markersFor(
  ownedIds: Iterable<string>,
  on: 'action' | 'condition',
  id: string,
  extra?: Readonly<Record<string, readonly RecordMarker[] | undefined>>,
): { sourceId: string; value?: string; note: string }[] {
  const out: { sourceId: string; value?: string; note: string }[] = [];
  const seen = new Set<string>();
  for (const sourceId of ownedIds) {
    if (seen.has(sourceId)) continue;
    seen.add(sourceId);
    for (const m of [...(RECORD_MARKERS[sourceId] ?? []), ...(extra?.[sourceId] ?? [])]) {
      if (m.on === on && m.id === id) out.push({ sourceId, value: m.value, note: m.note });
    }
  }
  return out;
}

/** "+2 circumstance" -> { value: 2, type: 'circumstance' }; a non-numeric phrase -> null. */
function parseBonus(bonus: string): { value: number; type: string } | null {
  const m = /^\s*([+-]?\d+)\s*(item|status|circumstance|untyped)?\b/i.exec(bonus);
  if (!m) return null;
  return { value: Number(m[1]), type: (m[2] ?? 'untyped').toLowerCase() };
}

/** Triggers compare as text: case, surrounding space and trailing punctuation are noise. */
const normalizeWhen = (when: string) => when.trim().toLowerCase().replace(/\s+/g, ' ').replace(/[.,;]+$/, '');

/**
 * PF2e stacking, applied to the star LIST and not just the maths.
 *
 * The totals already pool correctly (modes.ts poolTypedMods keeps the best bonus and the worst
 * penalty of each type). The list did not: every registry entry became its own line, so two items
 * that both grant "+1 item to Stealth while hiding" read as though you were getting +2.
 *
 * The owner's rule, and the whole of it: compare the trigger TEXT. Same type and the same trigger,
 * keep only the best bonus (and only the worst penalty) — you cannot have both. Any difference in
 * wording, or a different bonus type, and both stay: differently-worded triggers might not overlap,
 * and different types stack outright. A bonus with no number ("roll d10s instead of d8s") never pools.
 */
export function poolSituationalLines(lines: readonly SituationalLine[]): SituationalLine[] {
  const best = new Map<string, { line: SituationalLine; magnitude: number }>();
  const keyOf = (l: SituationalLine) => {
    const p = parseBonus(l.bonus);
    // Untyped bonuses SUM in PF2e, so they never supersede one another; an unparseable bonus has no
    // magnitude to compare. Both get a key nothing else can collide with.
    if (!p || p.type === 'untyped') return null;
    return `${p.type}|${p.value >= 0 ? '+' : '-'}|${normalizeWhen(l.when)}`;
  };

  for (const l of lines) {
    const key = keyOf(l);
    if (!key) continue;
    const mag = Math.abs(parseBonus(l.bonus)!.value);
    const cur = best.get(key);
    if (!cur || mag > cur.magnitude) best.set(key, { line: l, magnitude: mag });
  }

  const kept = new Set(Array.from(best.values(), (b) => b.line));
  return lines.filter((l) => {
    const key = keyOf(l);
    return key === null || kept.has(l);
  });
}

/** Whether any taken feat grants a situational bonus to this stat (drives the `*` cue). */
export function hasFeatSituational(
  featIds: Iterable<string>,
  ref: { kind: string; skill?: string; save?: string },
  extra?: ExtraSituational,
): boolean {
  for (const id of featIds) {
    for (const b of entriesFor(id, extra)) {
      if (b.targets.some((t) => targetMatches(t, ref))) return true;
    }
  }
  return false;
}
